    trailer[4]=isize&0xff; trailer[5]=(isize>>8)&0xff; trailer[6]=(isize>>16)&0xff; trailer[7]=(isize>>24)&0xff;
    fwrite(trailer,1,8,out);
    free(comp);
}

int read_gzip(FILE* in, FILE* out) {
    // decompress gzip file to out FILE*
    unsigned char header[10];
    if (fread(header,1,10,in)!=10) return -1;
    if (header[0]!=0x1f || header[1]!=0x8b) return -2;
    int flags = header[3];
    // skip extras, filename, comment, crc
    if (flags & 0x04) {
        unsigned char x[2]; fread(x,1,2,in);
        int xlen = x[0]|x[1]<<8;
        fseek(in,xlen,SEEK_CUR);
    }
    if (flags & 0x08) { int c; while((c=fgetc(in))!=0 && c!=EOF) ; }
    if (flags & 0x10) { int c; while((c=fgetc(in))!=0 && c!=EOF) ; }
    if (flags & 0x02) { fseek(in,2,SEEK_CUR); }
    z_stream strm; memset(&strm,0,sizeof(strm));
    inflateInit2(&strm, -15);
    unsigned char inbuf[8192], outbuf[8192];
    int ret;
    do {
        strm.avail_in = fread(inbuf,1,8192,in);
        if (strm.avail_in==0) break;
        strm.next_in = inbuf;
        do {
            strm.next_out = outbuf;
            strm.avail_out = 8192;
            ret = inflate(&strm, Z_NO_FLUSH);
            if (ret==Z_STREAM_ERROR || ret==Z_DATA_ERROR || ret==Z_MEM_ERROR) { inflateEnd(&strm); return -3; }
            size_t have = 8192 - strm.avail_out;
            fwrite(outbuf,1,have,out);
            if (ret==Z_STREAM_END) break;
        } while(strm.avail_out==0);
        if (ret==Z_STREAM_END) break;
    } while(1);
    inflateEnd(&strm);
    // trailer 8 bytes (ignore)
    return 0;
}

int main(int argc,char**argv){
    // test
    if (argc>1 && strcmp(argv[1],"decompress")==0){
        read_gzip(stdin, stdout);
        return 0;
    }
    // compress stdin to stdout gzip
    unsigned char* data=NULL; size_t cap=0, len=0;
    size_t chunk=8192;
    data=malloc(chunk);
    cap=chunk;
    int c;
    while((c=fgetc(stdin))!=EOF){
        if (len>=cap){cap*=2; data=realloc(data,cap);}
        data[len++]=c;
    }
    write_gzip(data,len,stdout, Z_DEFAULT_COMPRESSION);
    free(data);
    return 0;
}
