int read_file(const char* path, unsigned char** out, size_t* outSize) {
    FILE* f = fopen(path,"rb");
    if (!f) return -1;
    fseek(f,0,SEEK_END);
    long sz = ftell(f);
    fseek(f,0,SEEK_SET);
    if (sz<0) sz=0;
    unsigned char* buf = malloc(sz?sz:1);
    size_t read = fread(buf,1,sz,f);
    fclose(f);
    *out = buf;
    *outSize = read;
    return 0;
}

int write_file(const char* path, unsigned char* data, size_t size) {
    FILE* f = fopen(path,"wb");
    if (!f) return -1;
    size_t w = fwrite(data,1,size,f);
    fclose(f);
    return w==size?0:-1;
}

// gzip compress using manual header (no filename)
int gzip_compress(const unsigned char* src, size_t srcLen, unsigned char** dst, size_t* dstSize, int level) {
    z_stream strm; memset(&strm,0,sizeof(strm));
    int zlevel = Z_DEFAULT_COMPRESSION;
    // map zstd level 1-19 to gzip level 1-9 roughly
    if (level>=1 && level<=19) {
        // simple mapping: 1-3 ->1, 4-6->3, 7-9->6, 10-19->9
        if (level<=3) zlevel=1;
        else if (level<=6) zlevel=3;
        else if (level<=9) zlevel=6;
        else zlevel=9;
    }
    if (fastLevel>=0) {
        // fast => low compression
        zlevel=1;
    }
    int ret = deflateInit2(&strm, zlevel, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY);
    if (ret!=Z_OK) return -1;
    size_t bound = deflateBound(&strm, srcLen);
    unsigned char* comp = malloc(bound);
    strm.next_in = (unsigned char*)src;
    strm.avail_in = srcLen;
    strm.next_out = comp;
    strm.avail_out = bound;
    ret = deflate(&strm, Z_FINISH);
    if (ret!=Z_STREAM_END) { deflateEnd(&strm); free(comp); return -1; }
    size_t compLen = strm.total_out;
    deflateEnd(&strm);
    size_t total = 10 + compLen + 8;
    unsigned char* out = malloc(total);
    // header 10 bytes
    out[0]=0x1f; out[1]=0x8b; out[2]=8; out[3]=0;
    out[4]=out[5]=out[6]=out[7]=0;
    out[8]=0; out[9]=3;
    memcpy(out+10, comp, compLen);
    free(comp);
    uint32_t crc = crc32(0L, Z_NULL, 0);
    crc = crc32(crc, src, srcLen);
    uint32_t isize = srcLen;
    out[10+compLen+0]=crc&0xff;
    out[10+compLen+1]=(crc>>8)&0xff;
    out[10+compLen+2]=(crc>>16)&0xff;
    out[10+compLen+3]=(crc>>24)&0xff;
    out[10+compLen+4]=isize&0xff;
    out[10+compLen+5]=(isize>>8)&0xff;
    out[10+compLen+6]=(isize>>16)&0xff;
    out[10+compLen+7]=(isize>>24)&0xff;
    *dst = out;
    *dstSize = total;
    return 0;
}

int gzip_decompress(const unsigned char* src, size_t srcLen, unsigned char** dst, size_t* dstSize) {
    // parse gzip header then inflate
    if (srcLen<18) return -1;
    if (src[0]!=0x1f || src[1]!=0x8b) return -1;
    int flags = src[3];
    size_t pos=10;
    if (flags & 0x04) {
        if (pos+2>srcLen) return -1;
        int xlen = src[pos]|src[pos+1]<<8;
        pos+=2+xlen;
    }
    if (flags & 0x08) {
        while(pos<srcLen && src[pos]!=0) pos++;
        pos++;
    }
    if (flags & 0x10) {
        while(pos<srcLen && src[pos]!=0) pos++;
        pos++;
    }
    if (flags & 0x02) pos+=2;
    if (pos+8>srcLen) return -1;
    size_t compLen = srcLen - pos - 8;
    const unsigned char* comp = src+pos;
    z_stream strm; memset(&strm,0,sizeof(strm));
    int ret = inflateInit2(&strm, -15);
    if (ret!=Z_OK) return -1;
    size_t outCap = 1024*1024; // 1MB initial, grow
    unsigned char* out = malloc(outCap);
    strm.next_in = (unsigned char*)comp;
    strm.avail_in = compLen;
    strm.next_out = out;
    strm.avail_out = outCap;
    while(1) {
        ret = inflate(&strm, Z_NO_FLUSH);
        if (ret==Z_STREAM_END) break;
        if (ret!=Z_OK) { inflateEnd(&strm); free(out); return -1; }
        if (strm.avail_out==0) {
            size_t newCap = outCap*2;
            unsigned char* newOut = realloc(out, newCap);
            if (!newOut){inflateEnd(&strm); free(out); return -1;}
            out = newOut;
            strm.next_out = out + strm.total_out;
            strm.avail_out = newCap - strm.total_out;
            outCap = newCap;
        }
    }
    inflateEnd(&strm);
    *dst = out;
    *dstSize = strm.total_out;
    return 0;
}

// Zstd simple compress/decompress
int zstd_compress(const unsigned char* src, size_t srcLen, unsigned char** dst, size_t* dstSize, int level) {
    ZSTD_CCtx* cctx = ZSTD_createCCtx();
    size_t bound = ZSTD_compressBound(srcLen);
    unsigned char* out = malloc(bound);
    size_t cSize;
    if (dictData) {
        cSize = ZSTD_compress_usingDict(cctx, out, bound, src, srcLen, dictData, dictSize, level);
    } else {
        cSize = ZSTD_compressCCtx(cctx, out, bound, src, srcLen, level);
    }
    ZSTD_freeCCtx(cctx);
    if (ZSTD_isError(cSize)) { free(out); return -1; }
    *dst = out;
    *dstSize = cSize;
    return 0;
}

int zstd_decompress(const unsigned char* src, size_t srcLen, unsigned char** dst, size_t* dstSize) {
    // Need to get decompressed size if possible
    unsigned long long fcs = ZSTD_getFrameContentSize(src, srcLen);
    size_t outCap;
    if (fcs!=ZSTD_CONTENTSIZE_UNKNOWN && fcs!=ZSTD_CONTENTSIZE_ERROR) {
        outCap = (size_t)fcs;
        if (outCap==0) outCap=1;
    } else {
        // guess: srcLen * 4 maybe, but we will grow
        outCap = srcLen * 4 + 1024;
    }
    unsigned char* out = malloc(outCap);
    ZSTD_DCtx* dctx = ZSTD_createDCtx();
    size_t dSize;
    if (dictData) {
        dSize = ZSTD_decompress_usingDict(dctx, out, outCap, src, srcLen, dictData, dictSize);
    } else {
        dSize = ZSTD_decompressDCtx(dctx, out, outCap, src, srcLen);
    }
    if (ZSTD_isError(dSize)) {
        // try larger buffer iteratively if needed
        if (fcs==ZSTD_CONTENTSIZE_UNKNOWN) {
            // retry with larger
            for (int i=0;i<4;i++) {
                outCap *= 2;
                unsigned char* newOut = realloc(out, outCap);
                if (!newOut){ ZSTD_freeDCtx(dctx); free(out); return -1;}
                out = newOut;
                if (dictData) dSize = ZSTD_decompress_usingDict(dctx, out, outCap, src, srcLen, dictData, dictSize);
                else dSize = ZSTD_decompressDCtx(dctx, out, outCap, src, srcLen);
                if (!ZSTD_isError(dSize)) break;
            }
        }
        if (ZSTD_isError(dSize)) {
            ZSTD_freeDCtx(dctx);
            free(out);
            return -1;
        }
    }
    ZSTD_freeDCtx(dctx);
    *dst = out;
    *dstSize = dSize;
    return 0;
}

