int parse_zstd_frame(const unsigned char* src, size_t srcSize, FrameInfo* info) {
    if (srcSize<6) return -1;
    if (!(src[0]==0x28 && src[1]==0xb5 && src[2]==0x2f && src[3]==0xfd)) return -1;
    size_t pos=4;
    unsigned char fhd = src[pos++];
    int singleSegment = (fhd>>5)&1;
    int checksumFlag = (fhd>>2)&1;
    int dictIDFlag = fhd & 0x3;
    int fcsIDFlag = (fhd>>6)&0x3;
    // window descriptor if not single segment
    size_t windowSize=0;
    if (!singleSegment) {
        if (pos>=srcSize) return -1;
        unsigned char wd = src[pos++];
        unsigned exponent = wd>>3;
        unsigned mantissa = wd & 0x7;
        windowSize = (1ULL << (10+exponent)) + (1ULL << (10+exponent-3)) * mantissa;
        // Actually formula: windowSize = (1 << (10+exp)) + ...
    }
    unsigned dictID=0;
    if (dictIDFlag) {
        size_t didSize = 0;
        if (dictIDFlag==1) didSize=1;
        else if (dictIDFlag==2) didSize=2;
        else if (dictIDFlag==3) didSize=4;
        if (pos+didSize>srcSize) return -1;
        for (size_t i=0;i<didSize;i++) dictID |= src[pos+i] << (i*8);
        pos+=didSize;
    }
    unsigned long long fcs=0;
    size_t fcsSize=0;
    if (fcsIDFlag==0) { if (singleSegment) fcsSize=1; else fcsSize=0; }
    else if (fcsIDFlag==1) fcsSize=2;
    else if (fcsIDFlag==2) fcsSize=4;
    else if (fcsIDFlag==3) fcsSize=8;
    if (fcsSize) {
        if (pos+fcsSize>srcSize) return -1;
        for (size_t i=0;i<fcsSize;i++) fcs |= ((unsigned long long)src[pos+i]) << (i*8);
        if (fcsIDFlag==0) {} // single byte: value +256?
        pos+=fcsSize;
    }
    // For simplicity, windowSize if singleSegment = fcs
    if (singleSegment) windowSize = (size_t)fcs;
    if (windowSize==0) windowSize = fcs? (size_t)fcs : 0;

    // Find compressed size
    size_t cSize = ZSTD_findFrameCompressedSize(src, srcSize);
    if (ZSTD_isError(cSize)) return -1;

    info->compressedSize = cSize;
    info->decompressedSize = fcs;
    info->dictID = dictID;
    info->windowSize = windowSize;
    info->checksum = checksumFlag;
    return 0;
}

