// File list recursive collection
typedef struct {
    char** items;
    int count;
    int cap;
} FileList;

void filelist_init(FileList* fl){ fl->count=0; fl->cap=16; fl->items=malloc(sizeof(char*)*fl->cap); }
void filelist_add(FileList* fl, const char* path){ if(fl->count>=fl->cap){fl->cap*=2; fl->items=realloc(fl->items,sizeof(char*)*fl->cap);} fl->items[fl->count++]=strdup(path); }
void filelist_free(FileList* fl){ for(int i=0;i<fl->count;i++) free(fl->items[i]); free(fl->items); }

void collect_recursive(const char* dir, FileList* out) {
    DIR* d = opendir(dir);
    if (!d) return;
    struct dirent* ent;
    while((ent=readdir(d))!=NULL) {
        if (strcmp(ent->d_name,".")==0 || strcmp(ent->d_name,"..")==0) continue;
        char full[PATH_MAX];
        snprintf(full,sizeof(full),"%s/%s",dir,ent->d_name);
        struct stat st;
        if (lstat(full,&st)!=0) continue;
        if (S_ISLNK(st.st_mode) && !forceOverwrite) {
            if (quiet<1) fprintf(stderr, "Warning : %s is a symbolic link, ignoring \n", full);
            continue;
        }
        if (S_ISDIR(st.st_mode)) {
            collect_recursive(full, out);
        } else if (S_ISREG(st.st_mode)) {
            filelist_add(out, full);
        }
    }
    closedir(d);
}

