                    free(data);
                    continue;
                } else {
                    if (quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n", path);
                    free(outPath);
                    free(data);
                    errorRet=1;
                    continue;
                }
            }
            if (write_file(outPath,out,outSz)!=0) { fprintf(stderr,"zstd: %s: %s\n", outPath, strerror(errno)); free(outPath); free(data); free(out); errorRet=1; continue; }
            totalIn+=sz; totalOut+=outSz; totalFiles++;
            if (!quiet) {
