                fprintf(stderr,"%-21s : %zu bytes \n", path, outSz);
            }
            if (keepInput==0) unlink(path);
            free(out);
            free(outPath);
            free(data);
        }
    }

    if (totalFiles>1 && !quiet) {
        if (opMode==MODE_COMPRESS) {
            double ratio = totalIn? (double)totalOut*100.0/totalIn : 0;
            if (totalIn==0) fprintf(stderr,"  %d files compressed :  (%6zu B => %6zu B)\n", totalFiles, totalIn, totalOut);
