            }
            return 14;
        }
        // fake train: just copy first file? For now create simple file with size 112640? We'll create small dictionary by concatenating samples
        // For proper, try use ZDICT api if available
        // Attempt to use ZDICT_trainFromBuffer
        // We'll declare it
        extern size_t ZDICT_trainFromBuffer(void*, size_t, const void*, const size_t*, unsigned);
        extern unsigned ZDICT_isError(size_t);
        extern const char* ZDICT_getErrorName(size_t);
        size_t total=0;
        for(int i=0;i<finalInputs.c;i++){ struct stat st; if(stat(finalInputs.a[i],&st)==0) total+=st.st_size; }
        size_t* sizes=malloc(sizeof(size_t)*finalInputs.c);
        unsigned char* buf=malloc(total? total:1);
        size_t off=0;
        for(int i=0;i<finalInputs.c;i++){
            unsigned char* d; size_t ds;
            if(readFile(finalInputs.a[i],&d,&ds)!=0){ sizes[i]=0; continue; }
            memcpy(buf+off,d,ds);
            sizes[i]=ds;
            off+=ds;
            free(d);
        }
        size_t dictCap=112640;
        unsigned char* dictBuf=malloc(dictCap);
        size_t trained=ZDICT_trainFromBuffer(dictBuf,dictCap,buf,sizes,finalInputs.c);
        free(buf); free(sizes);
        if(ZDICT_isError(trained)){
            fprintf(stderr,"Error %zu : %s \n",trained,ZDICT_getErrorName(trained));
