    if(lastBType==1){
        // list
        if(finalInputs.c==0){ fprintf(stderr,"zstd: --list does not support reading from standard input \n"); return 1; }
        if(!quiet) printf("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename\n");
        int err=0;
        size_t totC=0, totU=0; int totF=0;
        for(int idx=0; idx<finalInputs.c; idx++){
            const char* path=finalInputs.a[idx];
            struct stat st;
            if(stat(path,&st)!=0){ if(quiet<1) fprintf(stderr,"zstd: can't stat %s : No such file or directory -- ignored \n",path); err=1; continue; }
            unsigned char* data; size_t sz;
            if(readFile(path,&data,&sz)!=0){ err=1; continue; }
            int isZ = (sz>=4 && data[0]==0x28 && data[1]==0xb5 && data[2]==0x2f && data[3]==0xfd);
            if(!isZ){
