            size_t offset=0;
            int frames=0;
            unsigned long long decompTot=0;
            int hasUnknown=0;
            size_t compTot=0;
            while(offset<sz){
                size_t fsz=ZSTD_findFrameCompressedSize(data+offset, sz-offset);
                if(ZSTD_isError(fsz)) break;
                unsigned long long fcs=ZSTD_getFrameContentSize(data+offset, fsz);
                if(fcs!=ZSTD_CONTENTSIZE_UNKNOWN && fcs!=ZSTD_CONTENTSIZE_ERROR) decompTot+=fcs;
                else hasUnknown=1;
                compTot+=fsz;
                frames++;
