                fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n");
                printf("%s \n# Zstandard Frames: %d\nDictID: 0\nWindow Size: %llu B (%llu B)\nCompressed Size: %zu B (%zu B)\n", path, frames, decompTot?decompTot: (unsigned long long)sz, decompTot?decompTot: (unsigned long long)sz, compTot, compTot);
                if(hasUnknown) printf("Decompressed Size: \nRatio: \nCheck: XXH64 \n\n");
                else {
                    double ratio = compTot? (double)decompTot/compTot : 0;
                    printf("Decompressed Size: %llu B (%llu B)\nRatio: %.4f\nCheck: XXH64 00000000\n\n", decompTot, decompTot, ratio);
                }
            } else {
                double ratio = compTot? (double)decompTot/compTot : 0;
                if(hasUnknown) printf("%6d %6d %8zu B %10s %6s %6s %s\n", frames,0,compTot,"","","XXH64",path);
                else printf("%6d %6d %8zu B %10llu B %6.3f %6s %s\n", frames,0,compTot,decompTot,ratio,"XXH64",path);
            }
            totC+=compTot; totU+=decompTot; totF+=frames;
            free(data);
        }
        if(finalInputs.c>1 && !verbose){
            printf("----------------------------------------------------------------- \n");
            printf("%6d %6d %8zu B %10zu B %6.3f %6s %d files\n", totF,0,totC,totU, totC? (double)totU/totC:0, "XXH64", finalInputs.c);
        }
        return err?1:0;
    }
    if(lastBType==2){
        // test
