            else if(fmt==2){ unsigned char* o; size_t ol; if(gzDecompress(data,len,&o,&ol)==0){ fwrite(o,1,ol,stdout); free(o); } else { if(passThrough==1||passThrough==-1) fwrite(data,1,len,stdout); else { if(quiet<1) fprintf(stderr,"zstd: /*stdin*\\: unsupported format \n"); free(data); return 1; } } }
            else { if(passThrough==1||passThrough==-1) fwrite(data,1,len,stdout); else { if(quiet<1) fprintf(stderr,"zstd: /*stdin*\\: unsupported format \n"); free(data); return 1; } }
            free(data);
            return 0;
        } else {
            for(int idx=0; idx<finalInputs.c; idx++){
                const char* path=finalInputs.a[idx];
                if(strcmp(path,"-")==0){
                    size_t cap=8192, len=0; unsigned char* data=malloc(cap);
                    int c; while((c=getchar())!=EOF){ if(len>=cap){cap*=2; data=realloc(data,cap);} data[len++]=c; }
                    int fmt=detect(data,len);
                    if(fmt==1){ unsigned char* o; size_t ol; if(zstdDecompress(data,len,&o,&ol)==0){ fwrite(o,1,ol,stdout); free(o); } else { if(passThrough==1||passThrough==-1) fwrite(data,1,len,stdout); else { free(data); return 1; } } }
                    else if(fmt==2){ unsigned char* o; size_t ol; if(gzDecompress(data,len,&o,&ol)==0){ fwrite(o,1,ol,stdout); free(o); } else { if(passThrough==1||passThrough==-1) fwrite(data,1,len,stdout); else { free(data); return 1; } } }
                    else { if(passThrough==1||passThrough==-1) fwrite(data,1,len,stdout); }
                    free(data);
                } else {
                    struct stat st; if(stat(path,&st)!=0){ if(quiet<1) fprintf(stderr,"zstd: can't stat %s : No such file or directory -- ignored \n",path); continue; }
                    unsigned char* data; size_t sz; if(readFile(path,&data,&sz)!=0) continue;
                    int fmt=detect(data,sz);
                    if(fmt==1){ unsigned char* o; size_t ol; if(zstdDecompress(data,sz,&o,&ol)==0){ fwrite(o,1,ol,stdout); free(o); } else { if(passThrough==1||passThrough==-1) fwrite(data,1,sz,stdout); else { if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path); free(data); return 1; } } }
                    else if(fmt==2){ unsigned char* o; size_t ol; if(gzDecompress(data,sz,&o,&ol)==0){ fwrite(o,1,ol,stdout); free(o); } else { if(passThrough==1||passThrough==-1) fwrite(data,1,sz,stdout); else { if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path); free(data); return 1; } } }
                    else { fwrite(data,1,sz,stdout); }
                    free(data);
                }
            }
            return 0;
        }
    }

    // compress/decompress normal
    size_t totIn=0, totOut=0; int totFiles=0; int errRet=0;
