        if(opCompress){
            if(outSingle){
                if(exists(outSingle) && !force && !prompt(outSingle)){ fprintf(stderr,"Not overwritten  \n \n"); free(data); return 1; }
                unsigned char* out; size_t outSz; int lvl=level; if(fast>=0) lvl=-fast;
                int ok = fmtGzip? gzCompress(data,len,&out,&outSz,lvl): zstdCompress(data,len,&out,&outSz,lvl);
                if(ok==0){ writeFile(outSingle,out,outSz); if(!quiet){ if(verbose) fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n"); if(isZstdmt) fprintf(stderr,"Note: 48 physical core(s) detected \n"); fprintf(stderr,"/*stdin*\\            :%6.2f%%   (%6zu B => %6zu B, %s) \n", len? (double)outSz*100.0/len:0, len, outSz, outSingle); } free(out); }
                free(data);
                return 0;
            } else if(stdoutFlag){
                unsigned char* out; size_t outSz; int lvl=level; if(fast>=0) lvl=-fast;
                int ok = fmtGzip? gzCompress(data,len,&out,&outSz,lvl): zstdCompress(data,len,&out,&outSz,lvl);
                if(ok==0){ fwrite(out,1,outSz,stdout); if(verbose && !quiet){ fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n/*stdin*\\            :%6.2f%%   (%6zu B => %6zu B, /*stdout*\\) \n", len? (double)outSz*100.0/len:0, len, outSz); } free(out); }
