        if(issym(path) && !force){ if(quiet<1) fprintf(stderr,"Warning : %s is a symbolic link, ignoring \n",path); errRet=1; continue; }
        unsigned char* data; size_t sz; if(readFile(path,&data,&sz)!=0){ errRet=1; continue; }
        if(opCompress){
            char* outPath=NULL;
            if(outFlat){
                const char* b=strrchr(path,'/'); b=b?b+1:path;
                const char* suf=fmtGzip?".gz":".zst";
                outPath=malloc(strlen(outFlat)+1+strlen(b)+6);
                sprintf(outPath,"%s/%s%s",outFlat,b,suf);
            } else if(outMirror){
                const char* suf=fmtGzip?".gz":".zst";
                outPath=malloc(strlen(outMirror)+strlen(path)+6);
                sprintf(outPath,"%s%s%s",outMirror,path,suf);
                char tmp[PATH_MAX]; strncpy(tmp,outPath,PATH_MAX); char* sl=strrchr(tmp,'/'); if(sl){ *sl=0; char cmd[PATH_MAX+20]; snprintf(cmd,sizeof(cmd),"mkdir -p \"%s\"",tmp); system(cmd); }
            } else {
                outPath=outCompPath(path);
            }
            if(exists(outPath) && !force && !prompt(outPath)){ fprintf(stderr,"Not overwritten  \n \n"); free(outPath); free(data); errRet=1; continue; }
            unsigned char* out; size_t outSz; int lvl=level; if(fast>=0) lvl=-fast;
            int ok = fmtGzip? gzCompress(data,sz,&out,&outSz,lvl): zstdCompress(data,sz,&out,&outSz,lvl);
