            totIn+=sz; totOut+=outSz; totFiles++;
            if(!quiet){
                if(verbose) fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n");
                if(isZstdmt) fprintf(stderr,"Note: 48 physical core(s) detected \n");
                if(sz==0) fprintf(stderr,"%-21s :  (%6zu B => %6zu B, %s) \n",path,sz,outSz,outPath);
                else fprintf(stderr,"%-21s :%6.2f%%   (%6zu B => %6zu B, %s) \n",path, (double)outSz*100.0/sz, sz, outSz, outPath);
