            free(out); free(outPath); free(data);
        } else {
            char* outPath=NULL;
            if(outFlat){
                char* base=outDecompPath(path);
                if(!base){ if(quiet<1) fprintf(stderr,"zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n",path); free(data); errRet=1; continue; }
                const char* b=strrchr(base,'/'); b=b?b+1:base;
                outPath=malloc(strlen(outFlat)+1+strlen(b)+1);
                sprintf(outPath,"%s/%s",outFlat,b);
                free(base);
            } else if(outMirror){
                char* base=outDecompPath(path);
                if(!base){ if(quiet<1) fprintf(stderr,"zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n",path); free(data); errRet=1; continue; }
                outPath=malloc(strlen(outMirror)+strlen(base)+2);
                sprintf(outPath,"%s%s",outMirror,base);
                char tmp[PATH_MAX]; strncpy(tmp,outPath,PATH_MAX); char* sl=strrchr(tmp,'/'); if(sl){ *sl=0; char cmd[PATH_MAX+20]; snprintf(cmd,sizeof(cmd),"mkdir -p \"%s\"",tmp); system(cmd); }
                free(base);
            } else {
                outPath=outDecompPath(path);
                if(!outPath){ if(quiet<1) fprintf(stderr,"zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n",path); free(data); errRet=1; continue; }
            }
            if(exists(outPath) && !force && !prompt(outPath)){ fprintf(stderr,"Not overwritten  \n \n"); free(outPath); free(data); errRet=1; continue; }
            int fmt=detect(data,sz);
            if(fmt==0){
                if(passThrough==1||force){
                    writeFile(outPath,data,sz);
                    if(!quiet) fprintf(stderr,"%-21s : %zu bytes \n",path,sz);
                    totIn+=sz; totOut+=sz; totFiles++;
                    if(keep==0) unlink(path);
                    free(outPath); free(data); continue;
                } else {
                    if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path);
                    free(outPath); free(data); errRet=1; continue;
                }
            }
            unsigned char* out; size_t outSz;
            int ok = (fmt==1)? zstdDecompress(data,sz,&out,&outSz) : gzDecompress(data,sz,&out,&outSz);
            if(!ok){
                if(passThrough==1||force){ writeFile(outPath,data,sz); if(!quiet) fprintf(stderr,"%-21s : %zu bytes \n",path,sz); if(keep==0) unlink(path); free(outPath); free(data); continue; }
                else { if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path); free(outPath); free(data); errRet=1; continue; }
            }
            if(writeFile(outPath,out,outSz)!=0){ fprintf(stderr,"zstd: %s: %s\n",outPath,strerror(errno)); free(outPath); free(data); free(out); errRet=1; continue; }
            totIn+=sz; totOut+=outSz; totFiles++;
            if(!quiet){ if(verbose) fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n"); fprintf(stderr,"%-21s : %zu bytes \n",path,outSz); }
            if(keep==0) unlink(path);
            free(out); free(outPath); free(data);
        }
    }
    if(totFiles>1 && !quiet && opCompress){ double r=totIn? (double)totOut*100.0/totIn:0; fprintf(stderr,"  %d files compressed : %6.2f%% (%6zu B => %6zu B)\n", totFiles, r, totIn, totOut); }
    return errRet?1:0;
}
