                if(passThrough==1||force){
                    writeFile(outPath,data,sz);
                    if(!quiet) fprintf(stderr,"%-21s : %zu bytes \n",path,sz);
                    totIn+=sz; totOut+=sz; totFiles++;
                    if(keep==0) unlink(path);
                    free(outPath); free(data); continue;
                } else {
                    if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path);
                    free(outPath); free(data); errRet=1; continue;
                }
            }
            unsigned char* out; size_t outSz;
            int ok = (fmt==1)? zstdDecompress(data,sz,&out,&outSz) : gzDecompress(data,sz,&out,&outSz);
            if(!ok){
                if(passThrough==1||force){ writeFile(outPath,data,sz); if(!quiet) fprintf(stderr,"%-21s : %zu bytes \n",path,sz); if(keep==0) unlink(path); free(outPath); free(data); continue; }
                else { if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path); free(outPath); free(data); errRet=1; continue; }
            }
            if(writeFile(outPath,out,outSz)!=0){ fprintf(stderr,"zstd: %s: %s\n",outPath,strerror(errno)); free(outPath); free(data); free(out); errRet=1; continue; }
