    if(fast>=0) zlvl=1;
    z_stream strm; memset(&strm,0,sizeof(strm));
    if(deflateInit2(&strm,zlvl,Z_DEFLATED,-15,8,Z_DEFAULT_STRATEGY)!=Z_OK) return -1;
    size_t bound=deflateBound(&strm,slen);
