}
int zstdCompress(const unsigned char* src,size_t slen, unsigned char** dst,size_t* dlen,int lvl){
    ZSTD_CCtx* cctx=ZSTD_createCCtx();
    size_t b=ZSTD_compressBound(slen);
    unsigned char* out=malloc(b);
    size_t cs;
    if(dictData) cs=ZSTD_compress_usingDict(cctx,out,b,src,slen,dictData,dictSize,lvl);
    else cs=ZSTD_compressCCtx(cctx,out,b,src,slen,lvl);
    ZSTD_freeCCtx(cctx);
    if(ZSTD_isError(cs)){ free(out); return -1; }
