}
int zstdDecompress(const unsigned char* src,size_t slen, unsigned char** dst,size_t* dlen){
    unsigned long long fcs=ZSTD_getFrameContentSize(src,slen);
    size_t cap;
    if(fcs!=ZSTD_CONTENTSIZE_UNKNOWN && fcs!=ZSTD_CONTENTSIZE_ERROR) cap=(size_t)fcs; else cap=slen*4+1024;
    if(cap==0) cap=1;
    unsigned char* out=malloc(cap);
    ZSTD_DCtx* dctx=ZSTD_createDCtx();
    size_t ds;
    if(dictData) ds=ZSTD_decompress_usingDict(dctx,out,cap,src,slen,dictData,dictSize);
    else ds=ZSTD_decompressDCtx(dctx,out,cap,src,slen);
    if(ZSTD_isError(ds)){
        for(int i=0;i<4;i++){
            cap*=2; unsigned char* no=realloc(out,cap);
            if(!no){ ZSTD_freeDCtx(dctx); free(out); return -1; }
            out=no;
            if(dictData) ds=ZSTD_decompress_usingDict(dctx,out,cap,src,slen,dictData,dictSize);
            else ds=ZSTD_decompressDCtx(dctx,out,cap,src,slen);
            if(!ZSTD_isError(ds)) break;
        }
        if(ZSTD_isError(ds)){ ZSTD_freeDCtx(dctx); free(out); return -1; }
    }
    ZSTD_freeDCtx(dctx);
    *dst=out; *dlen=ds; return 0;
}
int detect(const unsigned char* d,size_t s){
    if(s>=4 && d[0]==0x28 && d[1]==0xb5 && d[2]==0x2f && d[3]==0xfd) return 1;
    if(s>=2 && d[0]==0x1f && d[1]==0x8b) return 2;
    return 0;
}
char* outCompPath(const char* in){ size_t l=strlen(in); const char* suf=fmtGzip?".gz":".zst"; char* o=malloc(l+6); strcpy(o,in); strcat(o,suf); return o; }
char* outDecompPath(const char* in){
    const char* sufs[]={".zst",".tzst",".gz",".tgz",".xz",".lz4",".lzma",".bz2",NULL};
    size_t len=strlen(in);
    for(int i=0;sufs[i];i++){ size_t sl=strlen(sufs[i]); if(len>sl && strcmp(in+len-sl,sufs[i])==0){ char* o=malloc(len-sl+1); memcpy(o,in,len-sl); o[len-sl]=0; if(o[0]==0){free(o);return NULL;} return o; } }
    return NULL;
