            else if(strcmp(a,"--compress-literals")==0||strcmp(a,"--no-compress-literals")==0){ }
            else if(strcmp(a,"--row-match-finder")==0||strcmp(a,"--no-row-match-finder")==0){ }
            else if(strcmp(a,"--mmap-dict")==0||strcmp(a,"--no-mmap-dict")==0){ }
            else if(strcmp(a,"--sparse")==0||strcmp(a,"--no-sparse")==0){ }
            else if(strcmp(a,"--pass-through")==0){ passThrough=1; }
            else if(strcmp(a,"--no-pass-through")==0){ passThrough=0; }
            else if(strcmp(a,"--check")==0){ }
            else if(strcmp(a,"--no-check")==0){ }
            else if(strcmp(a,"--progress")==0||strcmp(a,"--no-progress")==0){ }
            else if(strcmp(a,"--asyncio")==0||strcmp(a,"--no-asyncio")==0){ }
            else if(strcmp(a,"--single-thread")==0){ }
            else if(strncmp(a,"--auto-threads",14)==0){ }
            else if(strncmp(a,"--jobsize",9)==0){ if(strchr(a,'=')==NULL) i++; }
            else if(strcmp(a,"--rsyncable")==0){ }
            else if(strcmp(a,"--exclude-compressed")==0){ excl=1; }
            else if(strcmp(a,"--test")==0){ opCompress=0; lastBType=2; }
            else if(strcmp(a,"--list")==0){ lastBType=1; }
            else if(strcmp(a,"-S")==0){ }
            else if(strncmp(a,"--split",7)==0){ if(strchr(a,'=')==NULL) i++; }
            else if(strncmp(a,"--priority",10)==0){ if(strchr(a,'=')==NULL) i++; }
            else if(strcmp(a,"--trace")==0){ i++; }
            else if(strncmp(a,"--trace=",8)==0){ }
            else if(strncmp(a,"--train",7)==0){ lastBType=4; }
            else if(strncmp(a,"--maxdict",9)==0){ if(strchr(a,'=')==NULL) i++; }
            else if(strncmp(a,"--dictID",8)==0){ if(strchr(a,'=')==NULL) i++; }
            else if(strcmp(a,"--patch-apply")==0){ }
            else {
                if(a[1]!='-'){
                    int pos=1;
                    while(a[pos]){
                        char c=a[pos];
                        if(c>='0'&&c<='9'){
                            int start=pos;
                            while(a[pos]>='0'&&a[pos]<='9') pos++;
                            char num[16]; int len=pos-start; if(len>15) len=15; memcpy(num,a+start,len); num[len]=0;
