char* outDecompPath(const char* in){ const char* sufs[]={".zst",".tzst",".gz",".tgz",".xz",".lz4",".lzma",".bz2",NULL}; size_t len=strlen(in); for(int i=0;sufs[i];i++){ size_t sl=strlen(sufs[i]); if(len>sl && strcmp(in+len-sl,sufs[i])==0){ char* o=malloc(len-sl+1); memcpy(o,in,len-sl); o[len-sl]=0; if(o[0]==0){free(o);return NULL;} return o; } } return NULL; }
