void flInit(FL* f){ f->c=0; f->cap=16; f->a=malloc(sizeof(char*)*f->cap); }
void flAdd(FL* f, const char* s){ if(f->c>=f->cap){f->cap*=2; f->a=realloc(f->a,sizeof(char*)*f->cap);} f->a[f->c++]=strdup(s); }
void collectRec(const char* dir, FL* out){ DIR* d=opendir(dir); if(!d) return; struct dirent* ent; while((ent=readdir(d))!=NULL){ if(strcmp(ent->d_name,".")==0||strcmp(ent->d_name,"..")==0) continue; char full[PATH_MAX]; snprintf(full,sizeof(full),"%s/%s",dir,ent->d_name); struct stat st; if(lstat(full,&st)!=0) continue; if(S_ISLNK(st.st_mode) && !force){ if(quiet<1) fprintf(stderr,"Warning : %s is a symbolic link, ignoring \n",full); continue; } if(S_ISDIR(st.st_mode)) collectRec(full,out); else if(S_ISREG(st.st_mode)) flAdd(out,full); } closedir(d); }

