    }
    if(lastBType==3){
        if(finalInputs.c==0){ printf(" 3#\n"); return 0; }
        for(int i=0;i<finalInputs.c;i++){ fprintf(stderr,"Loading %s...       \n", finalInputs.a[i]); printf(" 3#\n"); }
