            fprintf(stderr,"Proceed? (y/n): "); fflush(stderr);
            if(!fgets(line,sizeof(line),stdin) || (line[0]!='y'&&line[0]!='Y')){ fprintf(stderr,"Aborting... \n"); return 1; }
        }
        if(exists(outSingle) && !force && !prompt(outSingle)){ fprintf(stderr,"Not overwritten  \n \n"); return 1; }
        FILE* outF=fopen(outSingle,"wb");
        if(!outF){ fprintf(stderr,"zstd: %s: %s\n", outSingle, strerror(errno)); return 1; }
        for(int idx=0; idx<finalInputs.c; idx++){
            const char* path=finalInputs.a[idx];
            if(strcmp(path,"-")==0){
                size_t cap=8192, len=0; unsigned char* data=malloc(cap);
                int c; while((c=getchar())!=EOF){ if(len>=cap){cap*=2; data=realloc(data,cap);} data[len++]=c; }
                if(opCompress){
                    unsigned char* out; size_t outSz; int lvl=level; if(fast>=0) lvl=-fast;
                    int ok = fmtGzip? gzCompress(data,len,&out,&outSz,lvl): zstdCompress(data,len,&out,&outSz,lvl);
                    if(ok==0){ fwrite(out,1,outSz,outF); totIn+=len; totOut+=outSz; free(out); }
                    free(data);
                } else {
                    int fmt=detect(data,len);
                    unsigned char* out; size_t outSz; int ok=0;
                    if(fmt==1) ok = (zstdDecompress(data,len,&out,&outSz)==0);
                    else if(fmt==2) ok = (gzDecompress(data,len,&out,&outSz)==0);
                    else {
                        if(passThrough==1||force){ fwrite(data,1,len,outF); totIn+=len; totOut+=len; free(data); continue; }
                        else { free(data); fclose(outF); if(quiet<1) fprintf(stderr,"zstd: /*stdin*\\: unsupported format \n"); return 1; }
                    }
                    if(ok){ fwrite(out,1,outSz,outF); totIn+=len; totOut+=outSz; free(out); }
                    free(data);
                }
            } else {
                struct stat st; if(stat(path,&st)!=0){ if(quiet<1) fprintf(stderr,"zstd: can't stat %s : No such file or directory -- ignored \n",path); errRet=1; continue; }
                if(issym(path) && !force){ if(quiet<1) fprintf(stderr,"Warning : %s is a symbolic link, ignoring \n",path); errRet=1; continue; }
                unsigned char* data; size_t sz; if(readFile(path,&data,&sz)!=0){ errRet=1; continue; }
                if(opCompress){
                    unsigned char* out; size_t outSz; int lvl=level; if(fast>=0) lvl=-fast;
                    int ok = fmtGzip? gzCompress(data,sz,&out,&outSz,lvl): zstdCompress(data,sz,&out,&outSz,lvl);
                    if(ok==0){ fwrite(out,1,outSz,outF); totIn+=sz; totOut+=outSz; free(out); }
                    if(!quiet){
                        double ratio=sz? (double)outSz*100.0/sz:0;
                        if(verbose) fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n");
                        if(isZstdmt) fprintf(stderr,"Note: 48 physical core(s) detected \n");
                        fprintf(stderr,"%-21s :%6.2f%%   (%6zu B => %6zu B, %s) \n", path, ratio, sz, outSz, outSingle);
                    }
                    if(keep==0) unlink(path);
                    free(data);
                } else {
                    int fmt=detect(data,sz);
                    if(fmt==0){
                        if(passThrough==1||force){ fwrite(data,1,sz,outF); if(!quiet) fprintf(stderr,"%-21s : %zu bytes \n",path,sz); if(keep==0) unlink(path); free(data); continue; }
                        else { if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path); free(data); errRet=1; continue; }
                    }
                    unsigned char* out; size_t outSz;
                    int ok = (fmt==1)? (zstdDecompress(data,sz,&out,&outSz)==0) : (gzDecompress(data,sz,&out,&outSz)==0);
                    if(!ok){ if(passThrough==1||force){ fwrite(data,1,sz,outF); } else { if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path); free(data); errRet=1; continue; } }
                    else { fwrite(out,1,outSz,outF); if(!quiet){ if(verbose) fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n"); fprintf(stderr,"%-21s : %zu bytes \n",path,outSz); } free(out); if(keep==0) unlink(path); }
                    free(data);
                }
            }
            totFiles++;
        }
        fclose(outF);
        if(totFiles>1 && !quiet && opCompress){ double r=totIn? (double)totOut*100.0/totIn:0; fprintf(stderr,"  %d files compressed : %6.2f%% (%6zu B => %6zu B)\n", totFiles, r, totIn, totOut); }
        return errRet;
    }

    if(finalInputs.c==0){
        size_t cap=8192, len=0; unsigned char* data=malloc(cap);
        int c; while((c=getchar())!=EOF){ if(len>=cap){cap*=2; data=realloc(data,cap);} data[len++]=c; }
        if(opCompress){
            if(outSingle){
                if(exists(outSingle) && !force && !prompt(outSingle)){ fprintf(stderr,"Not overwritten  \n \n"); free(data); return 1; }
                unsigned char* out; size_t outSz; int lvl=level; if(fast>=0) lvl=-fast;
                int ok = fmtGzip? gzCompress(data,len,&out,&outSz,lvl): zstdCompress(data,len,&out,&outSz,lvl);
                if(ok==0){ writeFile(outSingle,out,outSz); if(!quiet){ if(verbose) fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n"); if(isZstdmt) fprintf(stderr,"Note: 48 physical core(s) detected \n"); fprintf(stderr,"/*stdin*\\            :%6.2f%%   (%6zu B => %6zu B, %s) \n", len? (double)outSz*100.0/len:0, len, outSz, outSingle); } free(out); }
                free(data); return 0;
            } else if(stdoutFlag){
                unsigned char* out; size_t outSz; int lvl=level; if(fast>=0) lvl=-fast;
                int ok = fmtGzip? gzCompress(data,len,&out,&outSz,lvl): zstdCompress(data,len,&out,&outSz,lvl);
                if(ok==0){ fwrite(out,1,outSz,stdout); if(verbose && !quiet){ fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n/*stdin*\\            :%6.2f%%   (%6zu B => %6zu B, /*stdout*\\) \n", len? (double)outSz*100.0/len:0, len, outSz); } free(out); }
                free(data); return 0;
            } else {
                unsigned char* out; size_t outSz; int lvl=level; if(fast>=0) lvl=-fast;
                int ok = fmtGzip? gzCompress(data,len,&out,&outSz,lvl): zstdCompress(data,len,&out,&outSz,lvl);
                if(ok==0) fwrite(out,1,outSz,stdout);
                free(data); if(ok==0) free(out); return 0;
            }
        } else {
            int fmt=detect(data,len);
            if(fmt==0){
                if(passThrough==1||force){ fwrite(data,1,len,stdout); free(data); return 0; }
                else { if(quiet<2) fprintf(stderr,"zstd: /*stdin*\\: unsupported format \n"); free(data); return 1; }
            }
            unsigned char* out; size_t outSz;
            int ok = (fmt==1)? zstdDecompress(data,len,&out,&outSz): gzDecompress(data,len,&out,&outSz);
            if(!ok){
                if(passThrough==1||force){ fwrite(data,1,len,stdout); free(data); return 0; }
                else { if(quiet<2) fprintf(stderr,"zstd: /*stdin*\\: unsupported format \n"); free(data); return 1; }
            }
            if(outSingle){
                if(exists(outSingle) && !force && !prompt(outSingle)){ fprintf(stderr,"Not overwritten  \n \n"); free(out); free(data); return 1; }
                writeFile(outSingle,out,outSz);
                if(!quiet){ if(verbose) fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n"); fprintf(stderr,"/*stdin*\\            : %zu bytes \n", outSz); }
            } else {
                fwrite(out,1,outSz,stdout);
            }
            free(out); free(data); return 0;
        }
    }

    if(stdoutFlag){
        int errRet=0;
        for(int idx=0; idx<finalInputs.c; idx++){
            const char* path=finalInputs.a[idx];
            if(strcmp(path,"-")==0){
                size_t cap=8192, len=0; unsigned char* data=malloc(cap);
                int c; while((c=getchar())!=EOF){ if(len>=cap){cap*=2; data=realloc(data,cap);} data[len++]=c; }
                if(opCompress){
                    unsigned char* out; size_t outSz; int lvl=level; if(fast>=0) lvl=-fast;
                    int ok = fmtGzip? gzCompress(data,len,&out,&outSz,lvl): zstdCompress(data,len,&out,&outSz,lvl);
                    if(ok==0){
                        fwrite(out,1,outSz,stdout);
                        if(verbose && !quiet){ fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n/*stdin*\\            :%6.2f%%   (%6zu B => %6zu B, /*stdout*\\) \n", len? (double)outSz*100.0/len:0, len, outSz); }
                        free(out);
                    }
                    free(data);
                } else {
                    int fmt=detect(data,len);
                    if(fmt==0){
                        if(passThrough==1||force){ fwrite(data,1,len,stdout); }
                        else { if(quiet<1) fprintf(stderr,"zstd: /*stdin*\\: unsupported format \n"); free(data); return 1; }
                    } else {
                        unsigned char* out; size_t outSz;
                        int ok = (fmt==1)? zstdDecompress(data,len,&out,&outSz): gzDecompress(data,len,&out,&outSz);
                        if(!ok){
                            if(passThrough==1||force){ fwrite(data,1,len,stdout); }
                            else { if(quiet<1) fprintf(stderr,"zstd: /*stdin*\\: unsupported format \n"); free(data); return 1; }
                        } else { fwrite(out,1,outSz,stdout); free(out); }
                    }
                    free(data);
                }
            } else {
                struct stat st; if(stat(path,&st)!=0){ if(quiet<1) fprintf(stderr,"zstd: can't stat %s : No such file or directory -- ignored \n",path); errRet=1; continue; }
                if(issym(path) && !force){ if(quiet<1) fprintf(stderr,"Warning : %s is a symbolic link, ignoring \n",path); errRet=1; continue; }
                unsigned char* data; size_t sz; if(readFile(path,&data,&sz)!=0){ errRet=1; continue; }
                if(opCompress){
                    unsigned char* out; size_t outSz; int lvl=level; if(fast>=0) lvl=-fast;
                    int ok = fmtGzip? gzCompress(data,sz,&out,&outSz,lvl): zstdCompress(data,sz,&out,&outSz,lvl);
                    if(ok==0){
                        fwrite(out,1,outSz,stdout);
                        if(!quiet){
                            if(verbose) fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n");
                            if(isZstdmt) fprintf(stderr,"Note: 48 physical core(s) detected \n");
                            if(verbose) fprintf(stderr,"%-21s :%6.2f%%   (%6zu B => %6zu B, /*stdout*\\) \n", path, sz? (double)outSz*100.0/sz:0, sz, outSz);
                        }
                        free(out);
                    }
                } else {
                    int fmt=detect(data,sz);
                    if(fmt==0){
                        if(passThrough==1||force){ fwrite(data,1,sz,stdout); }
                        else { if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path); free(data); errRet=1; continue; }
                    } else {
                        unsigned char* out; size_t outSz;
                        int ok = (fmt==1)? zstdDecompress(data,sz,&out,&outSz): gzDecompress(data,sz,&out,&outSz);
                        if(!ok){
                            if(passThrough==1||force){ fwrite(data,1,sz,stdout); }
                            else { if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path); free(data); errRet=1; continue; }
                        } else { fwrite(out,1,outSz,stdout); free(out); }
                    }
                }
                free(data);
            }
        }
        return errRet;
    }

    for(int idx=0; idx<finalInputs.c; idx++){
        const char* path=finalInputs.a[idx];
        if(strcmp(path,"-")==0) continue;
        struct stat st; if(stat(path,&st)!=0){ if(quiet<1) fprintf(stderr,"zstd: can't stat %s : No such file or directory -- ignored \n",path); errRet=1; continue; }
        if(isdir(path)){ if(!rec){ if(quiet<1) fprintf(stderr,"zstd: %s is a directory -- ignored \n",path); errRet=1; continue; } continue; }
        if(issym(path) && !force){ if(quiet<1) fprintf(stderr,"Warning : %s is a symbolic link, ignoring \n",path); errRet=1; continue; }
        unsigned char* data; size_t sz; if(readFile(path,&data,&sz)!=0){ errRet=1; continue; }
        if(opCompress){
            char* outPath=NULL;
            if(outFlat){
                const char* b=strrchr(path,'/'); b=b?b+1:path;
                const char* suf=fmtGzip?".gz":".zst";
                outPath=malloc(strlen(outFlat)+1+strlen(b)+6);
                sprintf(outPath,"%s/%s%s",outFlat,b,suf);
            } else if(outMirror){
                const char* suf=fmtGzip?".gz":".zst";
                outPath=malloc(strlen(outMirror)+strlen(path)+6);
                sprintf(outPath,"%s%s%s",outMirror,path,suf);
                char tmp[PATH_MAX]; strncpy(tmp,outPath,PATH_MAX); char* sl=strrchr(tmp,'/'); if(sl){ *sl=0; char cmd[PATH_MAX+20]; snprintf(cmd,sizeof(cmd),"mkdir -p \"%s\"",tmp); system(cmd); }
            } else {
                outPath=outCompPath(path);
            }
            if(exists(outPath) && !force){
                if(!prompt(outPath)){ fprintf(stderr,"Not overwritten  \n \n"); free(outPath); free(data); errRet=1; continue; }
            }
            unsigned char* out; size_t outSz; int lvl=level; if(fast>=0) lvl=-fast;
            int ok = fmtGzip? gzCompress(data,sz,&out,&outSz,lvl): zstdCompress(data,sz,&out,&outSz,lvl);
            if(ok!=0){ fprintf(stderr,"zstd: %s: compression failed \n",path); free(outPath); free(data); errRet=1; continue; }
            if(writeFile(outPath,out,outSz)!=0){ fprintf(stderr,"zstd: %s: %s\n",outPath,strerror(errno)); free(outPath); free(data); free(out); errRet=1; continue; }
            totIn+=sz; totOut+=outSz; totFiles++;
            if(!quiet){
                if(verbose) fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n");
                if(isZstdmt) fprintf(stderr,"Note: 48 physical core(s) detected \n");
                if(sz==0) fprintf(stderr,"%-21s :  (%6zu B => %6zu B, %s) \n",path,sz,outSz,outPath);
                else fprintf(stderr,"%-21s :%6.2f%%   (%6zu B => %6zu B, %s) \n",path, (double)outSz*100.0/sz, sz, outSz, outPath);
            }
            if(keep==0) unlink(path);
            free(out); free(outPath); free(data);
        } else {
            char* outPath=NULL;
            if(outFlat){
                char* base=outDecompPath(path);
                if(!base){ if(quiet<1) fprintf(stderr,"zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n",path); free(data); errRet=1; continue; }
                const char* b=strrchr(base,'/'); b=b?b+1:base;
                outPath=malloc(strlen(outFlat)+1+strlen(b)+1);
                sprintf(outPath,"%s/%s",outFlat,b);
                free(base);
            } else if(outMirror){
                char* base=outDecompPath(path);
                if(!base){ if(quiet<1) fprintf(stderr,"zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n",path); free(data); errRet=1; continue; }
                outPath=malloc(strlen(outMirror)+strlen(base)+2);
                sprintf(outPath,"%s%s",outMirror,base);
                char tmp[PATH_MAX]; strncpy(tmp,outPath,PATH_MAX); char* sl=strrchr(tmp,'/'); if(sl){ *sl=0; char cmd[PATH_MAX+20]; snprintf(cmd,sizeof(cmd),"mkdir -p \"%s\"",tmp); system(cmd); }
                free(base);
            } else {
                outPath=outDecompPath(path);
                if(!outPath){ if(quiet<1) fprintf(stderr,"zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n",path); free(data); errRet=1; continue; }
            }
            if(exists(outPath) && !force && !prompt(outPath)){ fprintf(stderr,"Not overwritten  \n \n"); free(outPath); free(data); errRet=1; continue; }
            int fmt=detect(data,sz);
            if(fmt==0){
                if(passThrough==1||force){
                    writeFile(outPath,data,sz);
                    if(!quiet) fprintf(stderr,"%-21s : %zu bytes \n",path,sz);
                    totIn+=sz; totOut+=sz; totFiles++;
                    if(keep==0) unlink(path);
                    free(outPath); free(data); continue;
                } else {
                    if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path);
                    free(outPath); free(data); errRet=1; continue;
                }
            }
            unsigned char* out; size_t outSz;
            int ok = (fmt==1)? zstdDecompress(data,sz,&out,&outSz) : gzDecompress(data,sz,&out,&outSz);
            if(!ok){
                if(passThrough==1||force){ writeFile(outPath,data,sz); if(!quiet) fprintf(stderr,"%-21s : %zu bytes \n",path,sz); if(keep==0) unlink(path); free(outPath); free(data); continue; }
                else { if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path); free(outPath); free(data); errRet=1; continue; }
            }
            if(writeFile(outPath,out,outSz)!=0){ fprintf(stderr,"zstd: %s: %s\n",outPath,strerror(errno)); free(outPath); free(data); free(out); errRet=1; continue; }
            totIn+=sz; totOut+=outSz; totFiles++;
            if(!quiet){ if(verbose) fprintf(stderr,"*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n"); fprintf(stderr,"%-21s : %zu bytes \n",path,outSz); }
            if(keep==0) unlink(path);
            free(out); free(outPath); free(data);
        }
    }
    if(totFiles>1 && !quiet && opCompress){ double r=totIn? (double)totOut*100.0/totIn:0; fprintf(stderr,"  %d files compressed : %6.2f%% (%6zu B => %6zu B)\n", totFiles, r, totIn, totOut); }
    return errRet?1:0;
}
