void shortHelp(){
    printf("Compress or decompress the INPUT file(s); reads from STDIN if INPUT is `-` or not provided.\n\n");
    printf("Usage: %s [OPTIONS...] [INPUT... | -] [-o OUTPUT]\n\n", progUsageName);
    printf("Options:\n");
    printf("  -o OUTPUT                     Write output to a single file, OUTPUT.\n");
    printf("  -k, --keep                    Preserve INPUT file(s). [Default] \n");
    printf("  --rm                          Remove INPUT file(s) after successful (de)compression to file.\n\n");
    printf("  -#                            Desired compression level, where `#` is a number between 1 and 19;\n");
    printf("                                lower numbers provide faster compression, higher numbers yield\n");
    printf("                                better compression ratios. [Default: 3]\n\n");
    printf("  -d, --decompress              Perform decompression.\n");
    printf("  -D DICT                       Use DICT as the dictionary for compression or decompression.\n\n");
    printf("  -f, --force                   Disable input and output checks. Allows overwriting existing files,\n");
    printf("                                receiving input from the console, printing output to STDOUT, and\n");
    printf("                                operating on links, block devices, etc. Unrecognized formats will be\n");
    printf("                                passed-through through as-is.\n\n");
    printf("  -h                            Display short usage and exit.\n");
    printf("  -H, --help                    Display full help and exit.\n");
    printf("  -V, --version                 Display the program version and exit.\n\n");
}
