int exists(const char* p){ struct stat st; return stat(p,&st)==0; }
int isdir(const char* p){ struct stat st; if(stat(p,&st)!=0) return 0; return S_ISDIR(st.st_mode); }
int issym(const char* p){ struct stat st; if(lstat(p,&st)!=0) return 0; return S_ISLNK(st.st_mode); }
int prompt(const char* p){ if(force) return 1; fprintf(stderr,"zstd: %s already exists; overwrite (y/n) ? ",p); fflush(stderr); char buf[16]; if(!fgets(buf,sizeof(buf),stdin)) return 0; return buf[0]=='y'||buf[0]=='Y'; }
int readFile(const char* path, unsigned char** out, size_t* sz){ FILE* f=fopen(path,"rb"); if(!f) return -1; fseek(f,0,SEEK_END); long s=ftell(f); fseek(f,0,SEEK_SET); if(s<0)s=0; unsigned char* b=malloc(s? s:1); size_t r=fread(b,1,s,f); fclose(f); *out=b; *sz=r; return 0; }
int writeFile(const char* path, unsigned char* d, size_t s){ FILE* f=fopen(path,"wb"); if(!f) return -1; size_t w=fwrite(d,1,s,f); fclose(f); return w==s?0:-1; }
int gzCompress(const unsigned char* src,size_t slen, unsigned char** dst,size_t* dlen,int lvl){ int zlvl=Z_DEFAULT_COMPRESSION; if(lvl>=1 && lvl<=19){ if(lvl<=3) zlvl=1; else if(lvl<=6) zlvl=3; else if(lvl<=9) zlvl=6; else zlvl=9; } if(fast>=0) zlvl=1; z_stream strm; memset(&strm,0,sizeof(strm)); if(deflateInit2(&strm,zlvl,Z_DEFLATED,-15,8,Z_DEFAULT_STRATEGY)!=Z_OK) return -1; size_t bound=deflateBound(&strm,slen); unsigned char* comp=malloc(bound); strm.next_in=(unsigned char*)src; strm.avail_in=slen; strm.next_out=comp; strm.avail_out=bound; if(deflate(&strm,Z_FINISH)!=Z_STREAM_END){ deflateEnd(&strm); free(comp); return -1; } size_t clen=strm.total_out; deflateEnd(&strm); size_t tot=10+clen+8; unsigned char* out=malloc(tot); out[0]=0x1f; out[1]=0x8b; out[2]=8; out[3]=0; out[4]=out[5]=out[6]=out[7]=0; out[8]=0; out[9]=3; memcpy(out+10,comp,clen); free(comp); unsigned int crc=crc32(0L,Z_NULL,0); crc=crc32(crc,src,slen); unsigned int isize=slen; out[10+clen]=crc&0xff; out[10+clen+1]=(crc>>8)&0xff; out[10+clen+2]=(crc>>16)&0xff; out[10+clen+3]=(crc>>24)&0xff; out[10+clen+4]=isize&0xff; out[10+clen+5]=(isize>>8)&0xff; out[10+clen+6]=(isize>>16)&0xff; out[10+clen+7]=(isize>>24)&0xff; *dst=out; *dlen=tot; return 0; }
int gzDecompress(const unsigned char* src,size_t slen, unsigned char** dst,size_t* dlen){ if(slen<18) return -1; if(src[0]!=0x1f||src[1]!=0x8b) return -1; int flags=src[3]; size_t pos=10; if(flags&0x04){ if(pos+2>slen) return -1; int xl=src[pos]|src[pos+1]<<8; pos+=2+xl; } if(flags&0x08){ while(pos<slen && src[pos]!=0) pos++; pos++; } if(flags&0x10){ while(pos<slen && src[pos]!=0) pos++; pos++; } if(flags&0x02) pos+=2; if(pos+8>slen) return -1; size_t clen=slen-pos-8; z_stream strm; memset(&strm,0,sizeof(strm)); if(inflateInit2(&strm,-15)!=Z_OK) return -1; size_t cap=1024*1024; unsigned char* out=malloc(cap); strm.next_in=(unsigned char*)src+pos; strm.avail_in=clen; strm.next_out=out; strm.avail_out=cap; int ret; while(1){ ret=inflate(&strm,Z_NO_FLUSH); if(ret==Z_STREAM_END) break; if(ret!=Z_OK){ inflateEnd(&strm); free(out); return -1; } if(strm.avail_out==0){ size_t nc=cap*2; unsigned char* no=realloc(out,nc); if(!no){ inflateEnd(&strm); free(out); return -1; } out=no; strm.next_out=out+strm.total_out; strm.avail_out=nc-strm.total_out; cap=nc; } } inflateEnd(&strm); *dst=out; *dlen=strm.total_out; return 0; }
int zstdCompress(const unsigned char* src,size_t slen, unsigned char** dst,size_t* dlen,int lvl){ ZSTD_CCtx* cctx=ZSTD_createCCtx(); size_t b=ZSTD_compressBound(slen); unsigned char* out=malloc(b); size_t cs; if(dictData) cs=ZSTD_compress_usingDict(cctx,out,b,src,slen,dictData,dictSize,lvl); else cs=ZSTD_compressCCtx(cctx,out,b,src,slen,lvl); ZSTD_freeCCtx(cctx); if(ZSTD_isError(cs)){ free(out); return -1; } *dst=out; *dlen=cs; return 0; }
int zstdDecompress(const unsigned char* src,size_t slen, unsigned char** dst,size_t* dlen){ unsigned long long fcs=ZSTD_getFrameContentSize(src,slen); size_t cap; if(fcs!=ZSTD_CONTENTSIZE_UNKNOWN && fcs!=ZSTD_CONTENTSIZE_ERROR) cap=(size_t)fcs; else cap=slen*4+1024; if(cap==0) cap=1; unsigned char* out=malloc(cap); ZSTD_DCtx* dctx=ZSTD_createDCtx(); size_t ds; if(dictData) ds=ZSTD_decompress_usingDict(dctx,out,cap,src,slen,dictData,dictSize); else ds=ZSTD_decompressDCtx(dctx,out,cap,src,slen); if(ZSTD_isError(ds)){ for(int i=0;i<4;i++){ cap*=2; unsigned char* no=realloc(out,cap); if(!no){ ZSTD_freeDCtx(dctx); free(out); return -1; } out=no; if(dictData) ds=ZSTD_decompress_usingDict(dctx,out,cap,src,slen,dictData,dictSize); else ds=ZSTD_decompressDCtx(dctx,out,cap,src,slen); if(!ZSTD_isError(ds)) break; } if(ZSTD_isError(ds)){ ZSTD_freeDCtx(dctx); free(out); return -1; } } ZSTD_freeDCtx(dctx); *dst=out; *dlen=ds; return 0; }
int detect(const unsigned char* d,size_t s){ if(s>=4 && d[0]==0x28 && d[1]==0xb5 && d[2]==0x2f && d[3]==0xfd) return 1; if(s>=2 && d[0]==0x1f && d[1]==0x8b) return 2; return 0; }
char* outCompPath(const char* in){ size_t l=strlen(in); const char* suf=fmtGzip?".gz":".zst"; char* o=malloc(l+6); strcpy(o,in); strcat(o,suf); return o; }
char* outDecompPath(const char* in){ const char* sufs[]={".zst",".tzst",".gz",".tgz",".xz",".lz4",".lzma",".bz2",NULL}; size_t len=strlen(in); for(int i=0;sufs[i];i++){ size_t sl=strlen(sufs[i]); if(len>sl && strcmp(in+len-sl,sufs[i])==0){ char* o=malloc(len-sl+1); memcpy(o,in,len-sl); o[len-sl]=0; if(o[0]==0){free(o);return NULL;} return o; } } return NULL; }
typedef struct{ char** a; int c; int cap; } FL;
void flInit(FL* f){ f->c=0; f->cap=16; f->a=malloc(sizeof(char*)*f->cap); }
void flAdd(FL* f, const char* s){ if(f->c>=f->cap){f->cap*=2; f->a=realloc(f->a,sizeof(char*)*f->cap);} f->a[f->c++]=strdup(s); }
void collectRec(const char* dir, FL* out){
    DIR* d=opendir(dir); if(!d) return;
    struct dirent* ent;
    while((ent=readdir(d))!=NULL){
        if(strcmp(ent->d_name,".")==0||strcmp(ent->d_name,"..")==0) continue;
        char full[PATH_MAX]; snprintf(full,sizeof(full),"%s/%s",dir,ent->d_name);
        struct stat st; if(lstat(full,&st)!=0) continue;
        if(S_ISLNK(st.st_mode) && !force){ if(quiet<1) fprintf(stderr,"Warning : %s is a symbolic link, ignoring \n",full); continue; }
        if(S_ISDIR(st.st_mode)) collectRec(full,out);
        else if(S_ISREG(st.st_mode)) flAdd(out,full);
    }
    closedir(d);
}

int main(int argc,char** argv){
    const char* bn0=mybn(argv[0]);
    progUsageName=bn0;
    char* base=progBase(bn0);
    if(strcmp(base,"zcat")==0||strcmp(base,"gzcat")==0||strcmp(base,"zstdcat")==0) isCat=1;
    if(strcmp(base,"gzip")==0){ isGzip=1; fmtGzip=1; }
    if(strcmp(base,"gunzip")==0||strcmp(base,"unzstd")==0||strcmp(base,"unxz")==0||strcmp(base,"unlz4")==0||strcmp(base,"unlzma")==0) isDecompDef=1;
    if(strcmp(base,"zstdmt")==0) isZstdmt=1;
    free(base);
    int firstInfoPos=-1; int firstInfoType=0; int v_before=0, q_before=0; int curV=0, curQ=0;
    int dashDash=0; int lastBType=0;
    for(int idx=1; idx<argc; idx++){
        char* a=argv[idx];
        if(!dashDash && strcmp(a,"--")==0){ dashDash=1; continue; }
        if(dashDash) continue;
        if(a[0]!='-'||strcmp(a,"-")==0) continue;
        if(a[0]=='-' && a[1]!='-'){
            for(int j=1;a[j];j++){
                char c=a[j];
                if(c=='v') curV++;
                else if(c=='q') curQ++;
                else if(c=='h' && firstInfoPos==-1){ firstInfoPos=idx; firstInfoType=1; v_before=curV; q_before=curQ; }
                else if(c=='H' && firstInfoPos==-1){ firstInfoPos=idx; firstInfoType=2; v_before=curV; q_before=curQ; }
                else if(c=='V' && firstInfoPos==-1){ firstInfoPos=idx; firstInfoType=3; v_before=curV; q_before=curQ; }
                else if(c=='l'){ lastBType=1; }
                else if(c=='t'){ lastBType=2; }
                else if(c=='b'){ lastBType=3; }
            }
        } else {
            if(strcmp(a,"-h")==0 && firstInfoPos==-1){ firstInfoPos=idx; firstInfoType=1; v_before=curV; q_before=curQ; }
            else if((strcmp(a,"-H")==0||strcmp(a,"--help")==0) && firstInfoPos==-1){ firstInfoPos=idx; firstInfoType=2; v_before=curV; q_before=curQ; }
            else if((strcmp(a,"-V")==0||strcmp(a,"--version")==0) && firstInfoPos==-1){ firstInfoPos=idx; firstInfoType=3; v_before=curV; q_before=curQ; }
            else if(strcmp(a,"--test")==0){ lastBType=2; }
            else if(strcmp(a,"--list")==0||strcmp(a,"-l")==0){ lastBType=1; }
            else if(strncmp(a,"-b",2)==0){ lastBType=3; }
            else if(strcmp(a,"-v")==0) curV++;
            else if(strcmp(a,"-q")==0) curQ++;
            else if(strcmp(a,"--verbose")==0) curV++;
            else if(strcmp(a,"--quiet")==0) curQ++;
        }
    }
    if(firstInfoPos!=-1){
        if(firstInfoType==1){ shortHelp(); return 0; }
        if(firstInfoType==2){ longHelp(); return 0; }
        if(firstInfoType==3){
            int net=v_before - q_before;
            if(isCat) net-=1;
            if(net<0){ printf("1.6.0\n"); }
            else if(net==0){ printf("*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n"); }
            else if(net==1){ printf("*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n*** supports: zstd, gzip\n"); }
            else { printf("*** Zstandard CLI (64-bit) v1.6.0, by Yann Collet ***\n*** supports: zstd, gzip\nzlib version 1.2.11\nlz4 version Unsupported\nlzma version Unsupported\nsupports Multithreading \n_POSIX_C_SOURCE defined: 200809L\n_POSIX_VERSION defined: 200809L \nPLATFORM_POSIX_VERSION defined: 200809L\n"); }
            return 0;
        }
    }

    FL inputFiles; flInit(&inputFiles);
    int opCompress=1;
    if(isDecompDef) opCompress=0;
    if(isCat) opCompress=-1;
    int stdoutFlag=0;
    int i=1; dashDash=0;
    while(i<argc){
        char* a=argv[i];
        if(!dashDash && strcmp(a,"--")==0){ dashDash=1; i++; continue; }
        if(!dashDash && a[0]=='-' && strcmp(a,"-")!=0){
            if(strcmp(a,"-o")==0){
                if(i+1>=argc){ fprintf(stderr,"error: missing command argument \n"); return 1; }
                outSingle=argv[++i];
            } else if(strncmp(a,"-o",2)==0 && strlen(a)>2){ outSingle=a+2; }
            else if(strcmp(a,"-D")==0){
                if(i+1>=argc){ fprintf(stderr,"error: missing command argument \n"); return 1; }
                dictFile=argv[++i];
            } else if(strncmp(a,"-D",2)==0 && strlen(a)>2){ dictFile=a+2; }
            else if(strcmp(a,"--filelist")==0){
                if(i+1>=argc){ fprintf(stderr,"error: missing command argument \n"); return 1; }
                filelist=argv[++i];
            } else if(strncmp(a,"--filelist=",11)==0){ filelist=a+11; }
            else if(strcmp(a,"--output-dir-flat")==0){
                if(i+1>=argc){ fprintf(stderr,"error: missing command argument \n"); return 1; }
                outFlat=argv[++i];
            } else if(strncmp(a,"--output-dir-flat=",20)==0){ outFlat=a+20; }
            else if(strcmp(a,"--output-dir-mirror")==0){
                if(i+1>=argc){ fprintf(stderr,"error: missing command argument \n"); return 1; }
                outMirror=argv[++i];
            } else if(strncmp(a,"--output-dir-mirror=",22)==0){ outMirror=a+22; }
            else if(strcmp(a,"--patch-from")==0){
                if(i+1>=argc){ fprintf(stderr,"error: missing command argument \n"); return 1; }
                patchFrom=argv[++i];
            } else if(strncmp(a,"--patch-from=",13)==0){ patchFrom=a+13; }
            else if(strcmp(a,"--format")==0){
                if(i+1>=argc){ fprintf(stderr,"error: missing command argument \n"); return 1; }
                char* f=argv[++i];
                if(strcmp(f,"zstd")==0) fmtGzip=0;
                else if(strcmp(f,"gzip")==0||strcmp(f,"gz")==0) fmtGzip=1;
                else { fprintf(stderr,"Incorrect parameter: --format=%s \n",f); shortHelp(); return 1; }
            } else if(strncmp(a,"--format=",9)==0){
                char* f=a+9;
                if(strcmp(f,"zstd")==0) fmtGzip=0;
                else if(strcmp(f,"gzip")==0||strcmp(f,"gz")==0) fmtGzip=1;
                else { fprintf(stderr,"Incorrect parameter: --format=%s \n",f); shortHelp(); return 1; }
            } else if(strcmp(a,"--stream-size")==0){ i++; }
            else if(strncmp(a,"--stream-size=",14)==0){ }
            else if(strcmp(a,"--size-hint")==0){ i++; }
            else if(strncmp(a,"--size-hint=",12)==0){ }
            else if(strncmp(a,"--target-compressed-block-size=",31)==0){ }
            else if(strcmp(a,"--fast")==0){ fast=1; }
            else if(strncmp(a,"--fast=",7)==0){
                char* v=a+7;
                if(*v=='\0'){ fprintf(stderr,"Incorrect parameter: --fast= \n"); shortHelp(); return 1; }
                char* end; long lv=strtol(v,&end,10);
                if(*end!='\0' || lv<=0){ fprintf(stderr,"Incorrect parameter: %s \n",a); shortHelp(); return 1; }
                fast=lv;
            } else if(strcmp(a,"--ultra")==0){ ultra=1; }
            else if(strcmp(a,"--best")==0){
                if(!isGzip){ fprintf(stderr,"Incorrect parameter: --best \n"); shortHelp(); return 1; }
                level=9;
            } else if(strcmp(a,"-n")==0||strcmp(a,"--no-name")==0){ }
            else if(strcmp(a,"--no-dictID")==0){ }
            else if(strcmp(a,"--compress-literals")==0||strcmp(a,"--no-compress-literals")==0){ }
            else if(strcmp(a,"--row-match-finder")==0||strcmp(a,"--no-row-match-finder")==0){ }
            else if(strcmp(a,"--mmap-dict")==0||strcmp(a,"--no-mmap-dict")==0){ }
            else if(strcmp(a,"--sparse")==0||strcmp(a,"--no-sparse")==0){ }
            else if(strcmp(a,"--pass-through")==0){ passThrough=1; }
