                        free(data);
                    } else {
                        int fmt=detect(data,sz);
                        if(fmt==0){
                            if(passThrough==1||force){ fwrite(data,1,sz,outF); if(!quiet) fprintf(stderr,"%-21s : %zu bytes \n",path,sz); if(keep==0) unlink(path); free(data); continue; }
                            else { if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path); free(data); errRet=1; continue; }
                        }
                        unsigned char* out; size_t outSz;
                        int ok = (fmt==1)? (zstdDecompress(data,sz,&out,&outSz)==0) : (gzDecompress(data,sz,&out,&outSz)==0);
                        if(!ok){ if(passThrough==1||force){ fwrite(data,1,sz,outF); } else { if(quiet<1) fprintf(stderr,"zstd: %s: unsupported format \n",path); free(data); errRet=1; continue; } }
