            if(totFiles>1 && !quiet && opCompress){ double r=totIn? (double)totOut*100.0/totIn:0; fprintf(stderr,"  %d files compressed : %6.2f%% (%6zu B => %6zu B)\n", totFiles, r, totIn, totOut); }
            return errRet;
        } else if(finalInputs.c==1){
