typedef struct ZSTD_DCtx_s ZSTD_DCtx;
extern size_t ZSTD_findFrameCompressedSize(const void*, size_t);
extern unsigned ZSTD_isError(size_t);
extern unsigned long long ZSTD_getFrameContentSize(const void*, size_t);
#define ZSTD_CONTENTSIZE_UNKNOWN (0ULL-1)
#define ZSTD_CONTENTSIZE_ERROR (0ULL-2)
int main(int argc,char**argv){
    const char* path = argv[1];
    FILE* f=fopen(path,"rb");
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    unsigned char* data=malloc(sz);
    fread(data,1,sz,f); fclose(f);
    size_t offset=0;
    while(offset<sz){
        size_t fsz=ZSTD_findFrameCompressedSize(data+offset, sz-offset);
        if(ZSTD_isError(fsz)){ printf("error find %zu\n",fsz); break; }
        unsigned long long fcs=ZSTD_getFrameContentSize(data+offset, fsz);
        printf("frame %zu fcs %llu\n",fsz,fcs);
        offset+=fsz;
    }
    free(data);
    return 0;
}
